create table if not exists public.order_installments (id uuid primary key default gen_random_uuid(),order_id uuid not null references public.orders(id) on delete cascade,installment_number integer not null,scheduled_amount numeric not null default 0,amount_paid numeric not null default 0,balance numeric not null default 0,status text not null default 'pending',due_date date,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(order_id,installment_number)); alter table public.order_installments enable row level security; create or replace function public.rebuild_order_installments(_order_id uuid) returns void language plpgsql security definer set search_path=public as $$ declare o public.orders; n integer; each_amount numeric; i integer; begin select * into o from public.orders where id=_order_id; if not found then raise exception 'Order not found'; end if; delete from public.order_installments where order_id=_order_id and amount_paid=0; n:=greatest(1,coalesce(o.installment_months,1)); each_amount:=case when n>0 then o.total_amount/n else o.total_amount end; for i in 1..n loop insert into public.order_installments(order_id,installment_number,scheduled_amount,amount_paid,balance,status) values(o.id,i,each_amount,0,each_amount,'pending') on conflict(order_id,installment_number) do nothing; end loop; end; $$; create or replace function public.allocate_land_payment(_order_id uuid,_amount numeric) returns jsonb language plpgsql security definer set search_path=public as $$ declare o public.orders; remaining numeric:=_amount; r record; applied numeric; total_paid numeric; new_balance numeric; begin if _amount<=0 then raise exception 'Payment amount must be greater than zero'; end if; select * into o from public.orders where id=_order_id for update; if not found then raise exception 'Order not found'; end if; if remaining>greatest(o.total_amount-coalesce(o.amount_paid,0),0) then raise exception 'Payment exceeds outstanding balance'; end if; perform public.rebuild_order_installments(_order_id); for r in select * from public.order_installments where order_id=_order_id and balance>0 order by installment_number for update loop exit when remaining<=0; applied:=least(remaining,r.balance); update public.order_installments set amount_paid=amount_paid+applied,balance=balance-applied,status=case when balance-applied<=0 then 'paid' else 'partial' end,updated_at=now() where id=r.id; remaining:=remaining-applied; end loop; total_paid:=coalesce(o.amount_paid,0)+_amount; new_balance:=greatest(o.total_amount-total_paid,0); update public.orders set amount_paid=total_paid,balance=new_balance,payment_status=case when new_balance<=0 then 'paid' else payment_status end,updated_at=now() where id=_order_id; return jsonb_build_object('order_id',_order_id,'amount_applied',_amount,'amount_paid',total_paid,'balance',new_balance); end; $$; grant execute on function public.allocate_land_payment(uuid,numeric) to authenticated;
